CREATE TABLE IF NOT EXISTS modsecurity_status (domain_id int unsigned NOT NULL, server_id int unsigned NOT NULL, revision int unsigned NOT NULL, applied_revision int unsigned NOT NULL DEFAULT 0, applied_json mediumtext DEFAULT NULL, state varchar(16) NOT NULL, message text NOT NULL, updated_at datetime NOT NULL, PRIMARY KEY(domain_id,server_id)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS modsecurity_diagnostic_result (domain_id int unsigned NOT NULL, server_id int unsigned NOT NULL, revision int unsigned NOT NULL, state varchar(16) NOT NULL, message text NOT NULL, result_json mediumtext NOT NULL, collected_at datetime NOT NULL, PRIMARY KEY(domain_id,server_id)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS modsecurity_server_status (server_id int unsigned NOT NULL, revision int unsigned NOT NULL, applied_revision int unsigned NOT NULL DEFAULT 0, applied_json mediumtext DEFAULT NULL, state varchar(16) NOT NULL, message text NOT NULL, updated_at datetime NOT NULL, PRIMARY KEY(server_id)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
